corrected_code:
from fastapi import APIRouter, Depends, HTTPException
from kubernetes_asyncio import client

router = APIRouter(prefix="/k8s/namespaces")

@router.get("/{namespace}/pods/{pod_name}/logs")
async def read_pod_logs(
    namespace: str,
    pod_name: str,
    tail_lines: int = 100,
    current_user: User = Depends(get_current_tenant_user),
    core_api: client.CoreV1Api = Depends(get_k8s_core_api)
):
    if namespace != current_user.tenant_namespace:
        raise HTTPException(status_code=403, detail="Unauthorized access to target namespace")

    try:
        logs = await core_api.read_namespaced_pod_log(
            name=pod_name,
            namespace=namespace,
            tail_lines=min(tail_lines, 500)
        )
    except client.exceptions.ApiException as e:
        raise HTTPException(status_code=e.status, detail=e.reason)

    return {
        "namespace": namespace,
        "pod_name": pod_name,
        "logs": logs
    }
